tools.example:
// Java: a second Solution dataset pointing at another study's solution
model.result().dataset().create("dset2", "Solution");
model.result().dataset("dset2").set("solution", "sol2");
model.result().dataset("dset2").label("Coarse mesh run");
model.result().create("pg2", "PlotGroup3D");
model.result("pg2").set("data", "dset2");

// Java: xy cut plane at z = 20 mm, plotted as a 2D surface plot
model.result().dataset().create("cpl1", "CutPlane");
model.result().dataset("cpl1").set("data", "dset1");
model.result().dataset("cpl1").set("quickplane", "xy");
model.result().dataset("cpl1").set("quickz", "0.02");
model.result().create("pg2", "PlotGroup2D");
model.result("pg2").set("data", "cpl1");
model.result("pg2").create("surf1", "Surface");
model.result("pg2").feature("surf1").set("expr", "T");
model.result("pg2").run();

// Java: cut line from (0,0,0) to (0.1,0,0.02) plotted as a 1D line graph
model.result().dataset().create("cln1", "CutLine3D");
model.result().dataset("cln1").set("data", "dset1");
model.result().dataset("cln1").set("genpoints", new double[][]{{0, 0, 0}, {0.1, 0, 0.02}});
model.result().create("pg3", 1);
model.result("pg3").set("data", "cln1");
model.result("pg3").create("lngr1", "LineGraph");
model.result("pg3").feature("lngr1").set("expr", "T");
model.result("pg3").run();

// Java: probe point, then evaluate temperature there
model.result().dataset().create("cpt1", "CutPoint3D");
model.result().dataset("cpt1").set("data", "dset1");
model.result().dataset("cpt1").set("pointx", "0.05");
model.result().dataset("cpt1").set("pointy", "0");
model.result().dataset("cpt1").set("pointz", "0.01");
model.result().numerical().create("pev1", "EvalPoint");
model.result().numerical("pev1").set("data", "cpt1");
model.result().numerical("pev1").setIndex("expr", "T", 0);
double T = model.result().numerical("pev1").getReal()[0][0];

// Java: total heat source in domain 1
model.result().numerical().create("int1", "IntVolume");
model.result().numerical("int1").set("data", "dset1");
model.result().numerical("int1").selection().set(1);
model.result().numerical("int1").setIndex("expr", "ht.Qtot", 0);
model.result().numerical("int1").setIndex("unit", "W", 0);
double Q = model.result().numerical("int1").getReal()[0][0];
System.out.println("Total heat = " + Q + " W");

% LiveLink for MATLAB: total current through boundary 43, two ways
I_node = mphint2(model, 'ec.normJ', 'surface', 'selection', 43);

% ...or via a Derived Values node stored in the model
model.result.numerical.create('int2', 'IntSurface');
model.result.numerical('int2').selection.set(43);
model.result.numerical('int2').setIndex('expr', 'ec.normJ', 0);
I_table = model.result.numerical('int2').getReal();

// Java: temperature and von Mises stress at the points of cut point dataset cpt1
model.result().numerical().create("pev1", "EvalPoint");
model.result().numerical("pev1").set("data", "cpt1");
model.result().numerical("pev1").setIndex("expr", "T", 0);
model.result().numerical("pev1").setIndex("unit", "degC", 0);
model.result().numerical("pev1").setIndex("expr", "solid.mises", 1);
double[][] values = model.result().numerical("pev1").getReal();

// Java: terminal current for every parameter value of a sweep
model.result().numerical().create("gev1", "EvalGlobal");
model.result().numerical("gev1").set("data", "dset2");
model.result().numerical("gev1").setIndex("expr", "ec.I0_1", 0);
model.result().numerical("gev1").setIndex("unit", "mA", 0);
model.result().table().create("tbl1", "Table");
model.result().numerical("gev1").set("table", "tbl1");
model.result().numerical("gev1").setResult();

// Java: evaluation group with an average surface stress and displacement
model.result().evaluationGroup().create("eg1", "EvaluationGroup");
model.result().evaluationGroup("eg1").set("data", "dset2");
model.result().evaluationGroup("eg1").create("av1", "AvSurface");
model.result().evaluationGroup("eg1").feature("av1").selection().set(1);
model.result().evaluationGroup("eg1").feature("av1").setIndex("expr", "solid.disp", 0);
model.result().evaluationGroup("eg1").feature("av1").setIndex("expr", "solid.mises", 1);
model.result().evaluationGroup("eg1").run();

// Java: create the group by type name or by dimension, then draw it
model.result().create("pg1", "PlotGroup3D");   // same as model.result().create("pg1", 3)
model.result("pg1").set("data", "dset1");
model.result("pg1").create("surf1", "Surface");
model.result("pg1").feature("surf1").set("expr", "T");
model.result("pg1").run();

// Java: temperature on the surface with a thermal colour table
model.result().create("pg1", "PlotGroup3D");
model.result("pg1").create("surf1", "Surface");
model.result("pg1").feature("surf1").set("expr", "T");
model.result("pg1").feature("surf1").set("unit", "degC");
model.result("pg1").feature("surf1").set("descr", "Temperature");
model.result("pg1").feature("surf1").set("colortable", "ThermalLight");
model.result("pg1").run();

// Java: slice plot of the velocity magnitude
model.result().create("pg5", "PlotGroup3D");
model.result("pg5").create("slc1", "Slice");
model.result("pg5").feature("slc1").set("expr", "spf.U");
model.result("pg5").feature("slc1").set("colortable", "Rainbow");
model.result("pg5").run();

// Java: 20 temperature contour lines on a 2D plot group
model.result().create("pg6", "PlotGroup2D");
model.result("pg6").create("con1", "Contour");
model.result("pg6").feature("con1").set("expr", "T");
model.result("pg6").feature("con1").set("unit", "degC");
model.result("pg6").run();

// Java: velocity streamlines coloured by speed
model.result().create("pg7", "PlotGroup3D");
model.result("pg7").create("str1", "Streamline");
model.result("pg7").feature("str1").setIndex("expr", "u", 0);
model.result("pg7").feature("str1").setIndex("expr", "v", 1);
model.result("pg7").feature("str1").setIndex("expr", "w", 2);
model.result("pg7").feature("str1").create("col1", "Color");
model.result("pg7").feature("str1").feature("col1").set("expr", "spf.U");
model.result("pg7").run();

// Java: temperature profile along cut line cln1
model.result().create("pg3", "PlotGroup1D");
model.result("pg3").set("data", "cln1");
model.result("pg3").create("lngr1", "LineGraph");
model.result("pg3").feature("lngr1").set("expr", "T");
model.result("pg3").feature("lngr1").set("unit", "degC");
model.result("pg3").run();

// Java: von Mises stress on the deformed shape
model.result().create("pg8", "PlotGroup3D");
model.result("pg8").create("surf1", "Surface");
model.result("pg8").feature("surf1").set("expr", "solid.mises");
model.result("pg8").feature("surf1").create("def1", "Deform");
model.result("pg8").feature("surf1").feature("def1").setIndex("expr", "u", 0);
model.result("pg8").feature("surf1").feature("def1").setIndex("expr", "v", 1);
model.result("pg8").feature("surf1").feature("def1").setIndex("expr", "w", 2);
model.result("pg8").run();

// Java: export temperature and heat flux to a CSV file
model.result().export().create("data1", "dset1", "Data");
model.result().export("data1").setIndex("expr", "T", 0);
model.result().export("data1").setIndex("expr", "ht.tfluxMag", 1);
model.result().export("data1").set("filename", "C:/work/field.csv");
model.result().export("data1").run();

// Java: animate plot group pg1 (COMSOL 6.3 syntax)
ExportFeature anim = model.result().export().create("anim1", "pg1", "Animation");
anim.set("plotgroup", "pg1");
anim.run();

// Java: build a 3D plot group with a deformed, stress-coloured surface
model.result().create("pg1", "PlotGroup3D");
model.result("pg1").set("data", "dset1");
model.result("pg1").create("surf1", "Surface");
model.result("pg1").feature("surf1").set("expr", "solid.mises");
model.result("pg1").feature("surf1").create("def1", "Deform");
model.result("pg1").run();

// Java: maximum temperature and total heat in one pass
model.result().numerical().create("max1", "MaxVolume");
model.result().numerical("max1").selection().all();
model.result().numerical("max1").setIndex("expr", "T", 0);
double Tmax = model.result().numerical("max1").getReal()[0][0];

model.result().numerical().create("int1", "IntVolume");
model.result().numerical("int1").selection().all();
model.result().numerical("int1").setIndex("expr", "ht.Qtot", 0);
double Q = model.result().numerical("int1").getReal()[0][0];

// Java: end of a batch script — write data and a movie, then save
model.result().export().create("data1", "dset1", "Data");
model.result().export("data1").setIndex("expr", "T", 0);
model.result().export("data1").set("filename", "out/T.csv");
model.result().export().create("anim1", "pg1", "Animation");
model.result().export("anim1").set("plotgroup", "pg1");
model.result().export().run();   // runs every export node
model.save("solved.mph");

// Java: re-solve, refresh the plot, then export the image data
model.param().set("L", "12[cm]");
model.study("std1").run();
model.result("pg1").run();
model.result().export("data1").run();
